// === Tab: mySketch ===
ArrayList<Attractor> attractors;
ArrayList<Agent> agents;

function setup(){   
  createCanvas(1024, 768);
  background(0);
  colorMode(HSB,360,100,100,100);
  noStroke();
  frameRate(60);

  attractors = new ArrayList<Attractor>();
  agents = new ArrayList<Agent>();

	let a = new Attractor(width/2,height/2, 50);	// central attractor
  attractors.add(a); 

  for(i = 0; i < 0; i++){
    var a = new Attractor();    
    attractors.add(a);
  }

  for(i = 0; i < 1500; i++){
    var a = new Agent();    
    agents.add(a);
  }
}

function draw(){

    fill(0,0,0,10);
    noStroke();
    rect(0,0,width,height);
    for(i = 0; i < agents.size(); i++){
      agents.get(i).update();
    }
  for(i = 0; i < attractors.size(); i++){
    attractors.get(i).update();
  }
}

function mouseClicked(){
  var a = new Attractor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),0.1);
  attractors.add(a);
}

class Agent {
  oPos;
  nPos;
  vel;
  mass;
  c;

  constructor(){																	// let created entirely randomly, no vairables specified.
    oPos = new PVector(0,0);
    nPos = new PVector(0,0);
    vel = new PVector(0,0);
    c = color(0,100,100); //color(random(360), 50, 70);
    mass = 1;
		radius=random (100, 350);
		speed = 0.5*sqrt(50*800/(2*radius));
		angle = random (0,2*PI);
		nPos = new PVector(width/2+radius*sin(angle), height/2 + radius*cos(angle))
    oPos = new PVector(nPos.x,nPos.y);
    vel = new PVector(speed*cos(angle),-speed*sin(angle));
//    reset();
  }

  function update(){
    let doReset = false;

    for(i = 0; i < attractors.size(); i++){
      var a = attractors.get(i);

      if(PVector.dist(nPos, a.pos) < 10){doReset = true;}             // if colission with attractor reset

      let d2 = pow(PVector.dist(nPos, a.pos),2);										// let distance attractor to agent
      let n = PVector.sub(a.pos,nPos);													  // vector attractor to agent	
      n.normalize();																									// normalise
      let f = 100 * (a.mass*mass) / d2;															// force magnitude 
      n.mult(f);																											// mag times direction to attractor 
      vel.add(n);																											// add to cumulaive acceleration (velocity change)
    }    
    nPos.add(vel);    																								// apply acceleration

		if(doReset == true) {reset();}																		// reset if collides with attractor
    if(nPos.x < 0){reset();}																					// or if out of bounds
    if(nPos.y < 0){reset();}
    if(nPos.x > width){reset();}
    if(nPos.y > height){reset();}

    c = color(vel.mag()*50,90,vel.mag()*15+30); 											// calc colour using velocity
    stroke(c);
    strokeWeight(3);
    line(oPos.x, oPos.y, nPos.x, nPos.y);															// draw trail
    oPos = new PVector(nPos.x,nPos.y);																// update previous position
  }

  function reset(){																								// where let relocate on collision or out of bounds
		radius = random (200, 400);																				
		speed = 0.5*sqrt(50*400/(2*radius));
		angle = random (0,2*PI);
		nPos = new PVector(width/2+radius*sin(angle), height/2 + radius*cos(angle))
    oPos = new PVector(nPos.x,nPos.y);
    vel = new PVector(speed*cos(angle),-speed*sin(angle));
	}
}

class Attractor {
  pos;
	vel;
  mass;

  constructor(x, y, m){    
    pos = new PVector(x, y);
		let ray = PVector.sub(pos,(width/2, height/2));
		vel = new PVector(-ray.y, ray.x);
    mass = m;
  }

  function update(){
    fill(0,0,100);
    noStroke();
    ellipse(pos.x, pos.y , 5, 5);
  }
}

